    # A uniform first row indicates a horizontal separator; otherwise the
    # color-2 line is a vertical separator.
    col = next((c for c in range(w)
                if all(g[r][c] == 2 for r in range(h))), None)
    if col is None:
        return g
    pts = [(r, c) for r in range(h) for c in range(w)
           if g[r][c] not in (2, 7, 8)]
    if not pts:
        return g
    left = min(c for r, c in pts)
    right = max(c for r, c in pts)
    shift = col + 1 - left if left > col else col - 1 - right
    original = [(r, c, g[r][c]) for r, c in pts]
    for r, c, _ in original:
        g[r][c] = 7
    for r, c, color in original:
        g[r][c + shift] = color
    edge = right + shift + 1 if shift < 0 else left + shift - 1
    if 0 <= edge < w:
        for r in range(h):
            g[r][edge] = 8
    return g

