def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The color-2 line is a divider. Place an 8-line immediately beyond
    # the object, on its side of the divider, without moving the object.
    col = next((c for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)
    if col is not None:
        pts = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] not in (1, 2, 7, 8)]
        if pts:
            left, right = min(c for r, c in pts), max(c for r, c in pts)
            edge = right + 1 if left > col else left - 1
            if 0 <= edge < w:
                for r in range(h):
                    g[r][edge] = 8
        return g
    divider = next((r for r in range(h) if all(v == 2 for v in g[r])), None)
    if divider is not None:
        pts = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] not in (2, 3, 7, 8)]
        if pts:
            top, bottom = min(r for r, c in pts), max(r for r, c in pts)
            edge = bottom + 1 if top > divider else top - 1
            if 0 <= edge < h:
                g[edge] = [8] * w
    return g

